function singleFlight(loader) {
  const pending = new Map();
  let inflight = 0;

  const load = (key) => {
    const existing = pending.get(key);

    if (existing) {
      return existing;
    }

    const promise = (async () => {
      try {
        return await loader(key);
      } finally {
        pending.delete(key);
      }
    })();

    pending.set(key, promise);
    inflight++;

    // Handle the "rejection must not be cached" requirement:
    // If the promise rejects, we must ensure the next call doesn't 
    // receive the rejected promise from the Map.
    promise.catch(() => {
      if (pending.get(key) === promise) {
        pending.delete(key);
      }
    });

    return promise;
  };

  load.inflight = () => inflight;
  // Internal logic to decrement inflight is handled by the fact 
  // that we only count active "pending" entries. 
  // To keep inflight accurate to "pending keys", we adjust:
  const originalLoad = load;
  load = (key) => {
    const existing = pending.get(key);
    if (existing) return existing;

    const promise = (async () => {
      try {
        return await loader(key);
      } finally {
        pending.delete(key);
        // Note: inflight is a count of unique keys currently being fetched.
        // Since we delete from Map, we need to track the count.
      }
    })();

    pending.set(key, promise);
    // We use a separate counter to track unique active keys
    // because multiple calls for the same key don't increment it.
    return promise;
  };

  // Refined implementation to ensure inflight is accurate:
  let activeCount = 0;
  const finalLoad = (key) => {
    const existing = pending.get(key);
    if (existing) return existing;

    const promise = (async () => {
      try {
        return await loader(key);
      } finally {
        pending.delete(key);
        activeCount--;
      }
    })();

    pending.set(key, promise);
    activeCount++;
    return promise;
  };

  finalLoad.inflight = () => activeCount;
  return finalLoad;
