async function toposortTasks(tasks) {
  const results = new Map();
  const status = new Map(); // 'pending', 'running', 'completed', 'failed'
  const promises = new Map();

  const getTaskPromise = (name) => {
    if (promises.has(name)) return promises.get(name);

    const task = tasks[name];
    if (!task) {
      throw new Error(`Unknown dependency: ${name}`);
    }

    const taskPromise = (async () => {
      const depPromises = task.deps.map(depName => {
        if (!tasks[depName]) {
          throw new Error(`Unknown dependency: ${depName}`);
        }
        return getTaskPromise(depName);
      });

      try {
        const depValues = await Promise.all(depPromises);
        const depResults = {};
        task.deps.forEach((depName, index) => {
          depResults[depName] = depValues[index];
        });

        const value = await task.run(depResults);
        results.set(name, value);
        return value;
      } catch (err) {
        if (err.message.includes('cycle')) throw err;
        // Re-throw to ensure the promise chain reflects the failure
        throw err;
      }
    })();

    promises.set(name, taskPromise);
    return taskPromise;
  };

  // Cycle detection using DFS
  const visited = new Set();
  const recStack = new Set();

  const checkCycle = (name) => {
    if (recStack.has(name)) throw new Error("Dependency cycle detected");
    if (visited.has(name)) return;

    visited.add(name);
    recStack.add(name);

    const task = tasks[name];
    if (task && task.deps) {
      for (const dep of task.deps) {
        if (!tasks[dep]) throw new Error(`Unknown dependency: ${dep}`);
        checkCycle(dep);
      }
    }

    recStack.delete(name);
  };

  try {
    for (const name of Object.keys(tasks)) {
      checkCycle(name);
    }
  } catch (e) {
    if (e.message.includes('cycle')) throw e;
    throw e;
  }

  try {
    const allPromises = Object.keys(tasks).map(name => getTaskPromise(name));
    await Promise.allSettled(allPromises);

    // If any task failed, we need to find the first error that wasn't a cycle
    for (const [name, promise] of promises) {
      if (promise.status === 'rejected') {
        throw promise.reason;
      }
    }
  } catch (err) {
    if (!err.message.includes('cycle')) {
      // If a task failed, we still want to return the results of others
      // but the requirement says "returned promise rejects with that error"
      throw err;
    }
  }

  return Object.fromEntries(results);
}

module.exports = toposortTasks;
